/** The candidate questions as recognizable templates (QTemplate). */
class MembershipStoreQuestions(model: Model) {
    val unappliedDepositCandidates = QTemplate.of(model, "Deposit", RefName("UnappliedDeposit"))
    val activeMemberCandidates = QTemplate.of(model, "Member", RefName("ActiveMember"))
    val unappliedChargeCandidates = QTemplate.of(model, "Charge", RefName("UnappliedCharge"))
    val delinquentCandidates = QTemplate.of(model, "Member", RefName("Delinquent"))
    val deepDelinquentCandidates = QTemplate.of(model, "Member", RefName("DeepDelinquent"))
    val openDelinquencyFlagCandidates = QTemplate.of(model, "DelinquencyFlag", RefName("OpenDelinquencyFlag"))
    val closedTicketCandidates = QTemplate.of(model, "Ticket", RefName("ClosedTicket"))
    val openTicketCandidates = QTemplate.of(model, "Ticket", RefName("OpenTicket"))
    val overdueTicketCandidates = QTemplate.of(model, "Ticket", RefName("OverdueTicket"))
    val highPriorityCandidates = QTemplate.of(model, "Ticket", RefName("HighPriority"))
    val needsAttentionCandidates = QTemplate.of(model, "Ticket", RefName("NeedsAttention"))
    val renewMembershipCandidates = QTemplate.of(model, "Member", model.rules.getValue("RenewMembership").condition)
    val suspendDelinquentsCandidates = QTemplate.of(model, "Member", model.rules.getValue("SuspendDelinquents").condition)
    val restoreServiceCandidates = QTemplate.of(model, "Member", model.rules.getValue("RestoreService").condition)
    val openDelinquencyEpisodeCandidates = QTemplate.of(model, "Member", model.rules.getValue("OpenDelinquencyEpisode").condition)
    val openAccountReviewCandidates = QTemplate.of(model, "Member", model.rules.getValue("OpenAccountReview").condition)
    val escalateUrgentCandidates = QTemplate.of(model, "Ticket", model.rules.getValue("EscalateUrgent").condition)
    val never2Candidates = QTemplate.of(model, "Visit", model.nevers[1].target)
}

