    raisedOn = fields["raisedOn"] as LocalDate,
)

fun EscalationRow.toRow(): Row = Row("Escalation", key, buildMap {
    put("ticket", ticket)
    put("raisedOn", raisedOn)
})

fun Map<String, Any?>.toClosedTicketCapture(): ClosedTicketCapture = ClosedTicketCapture(
    closedOn = this["closedOn"] as LocalDate,
    closedBy = this["closedBy"] as Ref.Persisted,
)

fun ClosedTicketCapture.toValues(): Map<String, Any?> = buildMap {
    put("closedOn", closedOn)
    put("closedBy", closedBy)
}
